(() => {
'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const STORAGE='cloe_lesson09_guided_mock_v1';
const domainOrder=['Vocabulary','Grammar','Expressions','Reading','Listening'];
const state={started:Date.now(),sections:new Set(),timing:'timed',tokens:5,index:0,answers:[],questions:[],timer:null,left:45,saved:false,checkpointStart:0,report:{}};
const normalize=s=>String(s??'').trim().toLowerCase().replace(/[’']/g,"'").replace(/[.,!?;:]/g,'').replace(/\s+/g,' ');
const shuffle=a=>{const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x};
const toast=t=>{const el=$('#toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),1700)};
const answerText=a=>Array.isArray(a)?a.join(' '):String(a??'');

const questions=[
// VOCABULARY 10
{id:'v1',domain:'Vocabulary',level:'A2',type:'choice',prompt:'We need to ___ the deadline if we want the project to stay on schedule.',choices:['meet','reach','arrive','catch'],answer:'meet',hint:'Think of the fixed business collocation with “deadline”.',explain:'The natural collocation is “meet a deadline”.',model:'deadline → fixed verb collocation → meet a deadline.'},
{id:'v2',domain:'Vocabulary',level:'A2+',type:'select',prompt:'Please ___ the attached form and return it by Friday.',choices:['complete','attend','achieve','deliver'],answer:'complete',hint:'Which verb means “fill in / finish a form”?',explain:'“Complete a form” is the standard professional collocation.',model:'form → complete / fill in.'},
{id:'v3',domain:'Vocabulary',level:'B1',type:'choice',prompt:'The manager asked us to ___ the issue before it affects more customers.',choices:['address','attend','assist','achieve'],answer:'address',hint:'Which verb means “deal with a problem”?',explain:'To “address an issue” means to deal with it.',model:'issue/problem → address, tackle or resolve.'},
{id:'v4',domain:'Vocabulary',level:'B1',type:'wordbank',prompt:'Complete the collocation: We need to ________ a decision before noon.',tokens:['make','do','give','create'],answer:'make',hint:'English uses a fixed verb before “decision”.',explain:'We say “make a decision”.',model:'decision → fixed collocation → make a decision.'},
{id:'v5',domain:'Vocabulary',level:'B1',type:'choice',prompt:'The new software should help us ___ the number of data-entry errors.',choices:['reduce','fall','lower down','decrease of'],answer:'reduce',hint:'You need a transitive verb directly before “the number”.',explain:'“Reduce the number of errors” is natural and grammatically correct.',model:'verb + object → reduce errors.'},
{id:'v6',domain:'Vocabulary',level:'B1+',type:'select',prompt:'All staff must ___ with the new safety procedure.',choices:['comply','apply','obey to','follow to'],answer:'comply',hint:'The expression is “___ with a rule/procedure”.',explain:'We say “comply with” a rule, policy or procedure.',model:'rule/procedure → comply with.'},
{id:'v7',domain:'Vocabulary',level:'B1+',type:'choice',prompt:'We will ___ the new process next month after the pilot phase ends.',choices:['implement','implant','installate','realise'],answer:'implement',hint:'Which verb means “put a process or plan into operation”?',explain:'“Implement” means put a plan, policy or process into effect.',model:'plan/process → implement.'},
{id:'v8',domain:'Vocabulary',level:'B2',type:'choice',prompt:'The proposal is technically possible, but we need to confirm whether it is financially ___.',choices:['feasible','sensible','available','accurate'],answer:'feasible',hint:'Look for the adjective meaning “realistically possible to do”.',explain:'“Feasible” means possible and practical enough to be achieved.',model:'possible + practical → feasible.'},
{id:'v9',domain:'Vocabulary',level:'B2',type:'select',prompt:'The team introduced a backup system to ___ the risk of data loss.',choices:['mitigate','cancel','avoid from','lower off'],answer:'mitigate',hint:'Which formal verb means “reduce the severity or likelihood of a risk”?',explain:'“Mitigate a risk” is a common professional collocation.',model:'risk → mitigate / reduce.'},
{id:'v10',domain:'Vocabulary',level:'B2',type:'choice',prompt:'The redesigned workflow should ___ the approval process by removing unnecessary steps.',choices:['streamline','stretch','postpone','broaden'],answer:'streamline',hint:'Think “make a process simpler and more efficient”.',explain:'“Streamline” means simplify a process to make it more efficient.',model:'process efficiency → streamline.'},

// GRAMMAR 10
{id:'g1',domain:'Grammar',level:'A2',type:'select',prompt:'She ___ the client every Monday morning.',choices:['calls','is calling','called','has called'],answer:'calls',hint:'“Every Monday” signals a repeated routine.',explain:'Use the present simple for habits and routines.',model:'every + time period → present simple.'},
{id:'g2',domain:'Grammar',level:'A2+',type:'reorder',prompt:'Put the polite request in the correct order.',tokens:['Could','you','send','me','the','updated','file','please'],answer:['Could','you','send','me','the','updated','file','please'],hint:'Modal + subject + base verb + object + please.',explain:'Correct order: “Could you send me the updated file, please?”',model:'Could + you + send + object + please.'},
{id:'g3',domain:'Grammar',level:'B1',type:'choice',prompt:'We ___ this supplier since 2022.',choices:['have worked with','work with','worked with','are working with'],answer:'have worked with',hint:'“Since 2022” gives a starting point for a situation continuing now.',explain:'Use the present perfect for a situation that began in the past and continues now.',model:'since + starting point → present perfect.'},
{id:'g4',domain:'Grammar',level:'B1',type:'choice',prompt:'If the customer confirms today, we ___ the order tomorrow.',choices:['will ship','ship','would ship','shipped'],answer:'will ship',hint:'This is a realistic future condition.',explain:'First conditional: if + present, will + base verb.',model:'real future condition → if + present / will + verb.'},
{id:'g5',domain:'Grammar',level:'B1',type:'select',prompt:'The invoices ___ every Friday by the finance team.',choices:['are processed','process','are processing','have process'],answer:'are processed',hint:'The focus is on the invoices, not the people doing the action.',explain:'Present passive: are + past participle.',model:'object receives action → passive.'},
{id:'g6',domain:'Grammar',level:'B1+',type:'input',prompt:'Complete with the correct form: By the time the client arrives, we ________ (finish) the presentation.',answer:'will have finished',alts:['we will have finished'],hint:'“By the time” + future point = completed before that point.',explain:'Use the future perfect: “will have finished”.',model:'by + future reference → will have + past participle.'},
{id:'g7',domain:'Grammar',level:'B1+',type:'choice',prompt:'The manager said that the deadline ___ the following week.',choices:['would be moved','will move','moves','has moving'],answer:'would be moved',hint:'Reported speech often shifts “will” to “would”. The deadline receives the action.',explain:'Reported speech + passive gives “would be moved”.',model:'said → backshift; deadline receives action → passive.'},
{id:'g8',domain:'Grammar',level:'B1+',type:'choice',prompt:'We agreed ___ the client before making any changes.',choices:['to contact','contacting','contact','to contacting'],answer:'to contact',hint:'The verb “agree” is normally followed by an infinitive.',explain:'“Agree to do something” is the correct structure.',model:'agree → to + base verb.'},
{id:'g9',domain:'Grammar',level:'B2',type:'choice',prompt:'If we ___ more time, we would test the solution more thoroughly.',choices:['had','have','would have','will have'],answer:'had',hint:'This is a hypothetical present situation.',explain:'Second conditional: if + past simple, would + base verb.',model:'hypothetical now → if + past / would + verb.'},
{id:'g10',domain:'Grammar',level:'B2',type:'choice',prompt:'Had we known about the delay earlier, we ___ the client sooner.',choices:['would have informed','would inform','had informed','will have informed'],answer:'would have informed',hint:'“Had we known…” is an inverted third conditional.',explain:'Third conditional result: would have + past participle.',model:'unreal past condition → would have + past participle.'},

// EXPRESSIONS 10
{id:'e1',domain:'Expressions',level:'A2',type:'choice',context:'A colleague speaks too quickly during a call.',prompt:'Choose the most natural response.',choices:['Could you say that again, please?','Repeat you.','Say again now.','I don’t catch nothing.'],answer:'Could you say that again, please?',hint:'Choose a polite, complete request for repetition.',explain:'“Could you say that again, please?” is natural and professional.',model:'function = request repetition → polite modal + clear request.'},
{id:'e2',domain:'Expressions',level:'A2+',type:'select',context:'You want to close a professional email politely.',prompt:'Choose the best sentence.',choices:['Thank you in advance for your help.','Thanks before.','I wait your return.','Answer me quickly.'],answer:'Thank you in advance for your help.',hint:'Avoid expressions translated word-for-word from French.',explain:'“Thank you in advance for your help” is a standard professional closing.',model:'closing → appreciation + polite expectation.'},
{id:'e3',domain:'Expressions',level:'B1',type:'choice',context:'You did not understand exactly what a colleague means.',prompt:'What is the best clarification question?',choices:['Could you clarify what you mean by that?','What you mean?','Explain me that.','I do not understand your phrase.'],answer:'Could you clarify what you mean by that?',hint:'Professional clarification often uses “Could you clarify…?”',explain:'This is a natural, polite request for clarification.',model:'clarification → Could you clarify what you mean by…?'},
{id:'e4',domain:'Expressions',level:'B1',type:'reorder',prompt:'Build a diplomatic disagreement.',tokens:['I','see','your','point','but','I','have','some','concerns'],answer:['I','see','your','point','but','I','have','some','concerns'],hint:'Acknowledge first, then introduce your concern.',explain:'“I see your point, but I have some concerns.” is a useful diplomatic disagreement.',model:'acknowledge → but → concern.'},
{id:'e5',domain:'Expressions',level:'B1',type:'choice',context:'A customer says the same mistake has happened twice.',prompt:'Choose the strongest professional response.',choices:['I understand why that’s frustrating. Let me look into what happened and come back to you with a solution.','It is not my problem.','Mistakes happen.','Calm down and explain again.'],answer:'I understand why that’s frustrating. Let me look into what happened and come back to you with a solution.',hint:'A strong response acknowledges, takes ownership and proposes action.',explain:'The best answer combines empathy, ownership and a clear next step.',model:'acknowledge → investigate → commit to follow-up.'},
{id:'e6',domain:'Expressions',level:'B1+',type:'choice',context:'You need to move a meeting to another time.',prompt:'Choose the most professional formulation.',choices:['Would it be possible to move our meeting to Thursday afternoon?','Change the meeting Thursday.','I move it Thursday, okay?','Can you displace the meeting?'],answer:'Would it be possible to move our meeting to Thursday afternoon?',hint:'Use a polite modal and a clear alternative.',explain:'“Would it be possible to…” is polite and natural for rescheduling.',model:'request change → polite modal + specific alternative.'},
{id:'e7',domain:'Expressions',level:'B1+',type:'choice',context:'Two urgent tasks cannot both be completed today.',prompt:'What is the best way to negotiate priorities?',choices:['Which of these two tasks should take priority today?','I cannot do both, choose.','What is the more important?','Tell me your priority fast.'],answer:'Which of these two tasks should take priority today?',hint:'Ask for a clear priority without sounding confrontational.',explain:'This formulation is direct, neutral and collaborative.',model:'constraint → ask for prioritisation.'},
{id:'e8',domain:'Expressions',level:'B2',type:'select',context:'You are not completely certain about a forecast.',prompt:'Choose the most appropriate hedging expression.',choices:['At this stage, it appears that demand may slow slightly.','Demand will definitely collapse.','Maybe demand maybe go down.','I guarantee demand is uncertain.'],answer:'At this stage, it appears that demand may slow slightly.',hint:'Professional uncertainty uses cautious language, not absolute claims.',explain:'“At this stage, it appears that…” and “may” appropriately hedge the statement.',model:'uncertainty → hedge + modal.'},
{id:'e9',domain:'Expressions',level:'B2',type:'choice',context:'A serious issue cannot be resolved at your level.',prompt:'Choose the best escalation phrase.',choices:['I think we should escalate this to the technical lead before we proceed.','I send this problem higher.','We make an escalation.','This is above me, not my issue.'],answer:'I think we should escalate this to the technical lead before we proceed.',hint:'Name the action, the person and the reason/timing.',explain:'This is clear, professional and solution-focused.',model:'issue beyond authority → propose escalation + next step.'},
{id:'e10',domain:'Expressions',level:'B2',type:'choice',context:'You need to interrupt politely in a meeting to correct an important factual point.',prompt:'Choose the best expression.',choices:['Sorry to interrupt, but could I clarify one point before we move on?','Stop, that is wrong.','I interrupt you now.','Can I cut you?'],answer:'Sorry to interrupt, but could I clarify one point before we move on?',hint:'Acknowledge the interruption and explain your purpose.',explain:'This phrase is polite, purposeful and appropriate for a professional meeting.',model:'soften interruption → clarify purpose → return to discussion.'},

// READING 10
{id:'r1',domain:'Reading',level:'A2',type:'choice',context:'NOTICE\nThe reception desk will close at 4:30 p.m. on Friday for staff training. Urgent deliveries should be left with Security at the rear entrance.',prompt:'Where should an urgent delivery be left after 4:30?',choices:['At reception','With Security','In the training room','At the main entrance'],answer:'With Security',hint:'Scan for “urgent deliveries”.',explain:'The notice directly says urgent deliveries should be left with Security.',model:'question keyword → scan → exact evidence.'},
{id:'r2',domain:'Reading',level:'A2+',type:'choice',context:'EMAIL\nYour order is ready for collection from Tuesday. Please bring your order confirmation and a photo ID. The collection desk is open from 8:00 to 18:00.',prompt:'What must the customer bring?',choices:['A payment receipt only','A photo ID and confirmation','A delivery address','A company badge'],answer:'A photo ID and confirmation',hint:'Look for the sentence beginning “Please bring…”.',explain:'The email requires both the order confirmation and a photo ID.',model:'required items → locate “Please bring”.'},
{id:'r3',domain:'Reading',level:'B1',type:'choice',context:'MESSAGE\nThe software update planned for tonight has been postponed because the vendor identified a compatibility issue during final testing. A new deployment date will be confirmed after the technical review tomorrow.',prompt:'Why was the update postponed?',choices:['The technical team is unavailable','A compatibility problem was found','The vendor changed its contract','Tomorrow’s review was cancelled'],answer:'A compatibility problem was found',hint:'Focus on the cause introduced by “because”.',explain:'The vendor identified a compatibility issue during final testing.',model:'why? → because → cause.'},
{id:'r4',domain:'Reading',level:'B1',type:'textorder',context:'PROCEDURE\nPut the customer-record process in the safest logical order.',prompt:'Order the steps.',tokens:['Check the customer record.','Confirm the requested change.','Update the system.','Send written confirmation.'],answer:['Check the customer record.','Confirm the requested change.','Update the system.','Send written confirmation.'],hint:'Verify first; communicate after the update.',explain:'A safe sequence is check → confirm → update → confirm in writing.',model:'verification before action; confirmation after action.'},
{id:'r5',domain:'Reading',level:'B1',type:'input',context:'CHAT\nThe client can meet on Wednesday morning or Thursday after 3 p.m. They are unavailable on Friday.',prompt:'Type the earliest available day.',answer:'Wednesday',alts:['wednesday morning'],hint:'Compare the two available options.',explain:'Wednesday morning is earlier than Thursday after 3 p.m.',model:'earliest available option → Wednesday.'},
{id:'r6',domain:'Reading',level:'B1+',type:'choice',context:'SUPPLIER MESSAGE\nWe can still deliver on Tuesday, provided that the revised purchase order reaches us before 5 p.m. today. If we receive it later, the shipment will move to Thursday.',prompt:'What condition must be met for Tuesday delivery?',choices:['The order must arrive before 5 p.m. today','Payment must be made on Thursday','The supplier must call before noon','The shipment must leave today'],answer:'The order must arrive before 5 p.m. today',hint:'Look for “provided that”.',explain:'Tuesday delivery depends on receiving the revised purchase order before 5 p.m. today.',model:'condition signal → provided that → required action.'},
{id:'r7',domain:'Reading',level:'B1+',type:'choice',context:'MEETING MINUTES\nThe team agreed to keep the current launch date. Marketing will revise the customer message by Wednesday, while Operations will confirm stock levels before noon on Thursday. A final go/no-go call will take place Thursday afternoon.',prompt:'What must Operations do before the final call?',choices:['Confirm stock levels','Revise the customer message','Move the launch date','Contact every customer'],answer:'Confirm stock levels',hint:'Identify the Operations responsibility and timeline.',explain:'Operations must confirm stock levels before noon Thursday.',model:'role + deadline → Operations → confirm stock.'},
{id:'r8',domain:'Reading',level:'B2',type:'choice',context:'SHORT REPORT\nCustomer satisfaction improved this quarter despite a rise in average response time. The survey comments suggest that customers valued clearer explanations and more consistent follow-up, even when their issue took longer to resolve.',prompt:'What best explains the improved satisfaction?',choices:['Customers received clearer communication and follow-up','Response times became shorter','Fewer issues were reported','Customers stopped contacting support'],answer:'Customers received clearer communication and follow-up',hint:'Do not assume faster service caused the improvement; the text says response time increased.',explain:'The report links higher satisfaction to clearer explanations and consistent follow-up.',model:'contrast “despite” → improvement came from quality, not speed.'},
{id:'r9',domain:'Reading',level:'B2',type:'choice',context:'POLICY NOTE\nEmployees may work remotely up to three days per week, subject to operational requirements and manager approval. The policy is intended to increase flexibility, but it does not create an automatic entitlement to specific remote-working days.',prompt:'Which statement is accurate?',choices:['Remote work depends on operational needs and approval','Every employee can choose any three days','Managers cannot refuse a request','The policy guarantees fixed remote days'],answer:'Remote work depends on operational needs and approval',hint:'Pay attention to “subject to” and “does not create an automatic entitlement”.',explain:'The policy allows flexibility but conditions it on operational requirements and approval.',model:'permission + conditions → not an automatic right.'},
{id:'r10',domain:'Reading',level:'B2',type:'choice',context:'PROJECT UPDATE\nThe pilot achieved the expected efficiency gains, but adoption was uneven across teams. Interviews indicate that the main obstacle was not the software itself; several managers had not allocated enough time for staff training. The next phase will therefore focus on implementation support rather than further technical changes.',prompt:'What is the main implication for the next phase?',choices:['Training and implementation support need more attention','The software must be replaced','Efficiency targets should be reduced','The pilot should be cancelled'],answer:'Training and implementation support need more attention',hint:'Identify the real cause of uneven adoption and the stated next focus.',explain:'The obstacle was insufficient training time, so the next phase focuses on implementation support.',model:'problem cause → insufficient training → next action = support.'},

// LISTENING 10
{id:'l1',domain:'Listening',level:'A2',type:'listen-choice',audio:'Good morning. The meeting has moved from room twelve to room twenty. It will still start at nine fifteen.',prompt:'What changed?',choices:['The start time','The room','The day','The participants'],answer:'The room',hint:'Listen for “moved from… to…”.',explain:'Only the room changed, from 12 to 20.',model:'target = change → old room → new room.'},
{id:'l2',domain:'Listening',level:'A2+',type:'listen-input',audio:'Your appointment is on Thursday the thirteenth at three thirty in the afternoon.',prompt:'Type the appointment day and date. Example: Monday 12',answer:'Thursday 13',alts:['thursday 13','thursday the 13th','thursday 13th'],hint:'Separate the date from the time.',explain:'The appointment is Thursday the 13th at 3:30 p.m.',model:'day/date → Thursday 13; time is separate.'},
{id:'l3',domain:'Listening',level:'B1',type:'listen-choice',audio:'I originally asked for fifty units, but the customer has changed the order. Please send fifteen units in the first shipment and forty-five in the second.',prompt:'How many units are required for the first shipment?',choices:['15','50','40','45'],answer:'15',hint:'The speaker corrects the original quantity.',explain:'The original 50 is no longer the required first shipment; the new quantity is 15.',model:'old number → correction → new number.'},
{id:'l4',domain:'Listening',level:'B1',type:'listen-choice',audio:'Hi, this is a message for the service team. The customer says the printer turns on normally, but it loses the network connection after about five minutes. Please call them before four o’clock today.',prompt:'What is the main technical problem?',choices:['The printer loses its network connection','The printer will not turn on','The customer has no electricity','The printer is out of paper'],answer:'The printer loses its network connection',hint:'Distinguish what works from what fails.',explain:'The printer turns on normally; the network connection is the problem.',model:'contrast → power works / network fails.'},
{id:'l5',domain:'Listening',level:'B1',type:'listen-choice',audio:'We can approve the request today as long as the revised budget is attached to the form. Without that document, Finance will return the request.',prompt:'What is required for approval?',choices:['The revised budget must be attached','The form must be sent next week','Finance must call the manager','The request must be printed'],answer:'The revised budget must be attached',hint:'Listen for the condition introduced by “as long as”.',explain:'Approval depends on attaching the revised budget.',model:'condition → as long as → required document.'},
{id:'l6',domain:'Listening',level:'B1+',type:'listen-choice',audio:'The client was disappointed by the delay, but they appreciated that we contacted them before they had to chase us. They have agreed to the new delivery date.',prompt:'What helped maintain the relationship?',choices:['Proactive communication','A lower price','A shorter delivery time','A new supplier'],answer:'Proactive communication',hint:'What did the client appreciate?',explain:'The client appreciated being contacted proactively before needing to follow up.',model:'relationship positive → appreciated proactive contact.'},
{id:'l7',domain:'Listening',level:'B1+',type:'listen-input',audio:'The training was initially planned for Tuesday, but we have moved it to Friday the twenty-third because the trainer is unavailable earlier in the week.',prompt:'Type the new day and date. Example: Monday 12',answer:'Friday 23',alts:['friday 23','friday the 23rd','friday 23rd'],hint:'Ignore the original Tuesday and catch the revised date.',explain:'The new date is Friday the 23rd.',model:'old plan → but → revised plan.'},
{id:'l8',domain:'Listening',level:'B2',type:'listen-choice',audio:'I am not opposed to the proposal in principle. My concern is that we are committing to the full rollout before we have enough evidence from the pilot. I would prefer a phased approach.',prompt:'What is the speaker’s position?',choices:['They support the idea but want a more gradual rollout','They completely reject the proposal','They want to cancel the pilot immediately','They believe no further evidence is needed'],answer:'They support the idea but want a more gradual rollout',hint:'Listen for contrast between general support and a specific concern.',explain:'The speaker is not opposed in principle but prefers a phased approach.',model:'stance = qualified support + concern + alternative.'},
{id:'l9',domain:'Listening',level:'B2',type:'listen-choice',audio:'We are likely to finish on schedule, provided the final test does not reveal any critical defects. If it does, we will need at least two additional days.',prompt:'How certain is the speaker about finishing on schedule?',choices:['Likely, but conditional on the final test','Completely certain','Very unlikely','Already impossible'],answer:'Likely, but conditional on the final test',hint:'Pay attention to “likely” and “provided”.',explain:'The speaker expects to finish on time, but only if no critical defect is found.',model:'probability + condition → likely, not guaranteed.'},
{id:'l10',domain:'Listening',level:'B2',type:'listen-choice',audio:'The figures look encouraging at first glance. However, most of the growth came from one unusually large contract, so I would be cautious about treating this as a long-term trend.',prompt:'What is the speaker warning against?',choices:['Assuming the growth will necessarily continue','Accepting a large contract','Reviewing the figures again','Comparing different quarters'],answer:'Assuming the growth will necessarily continue',hint:'The speaker questions whether one exceptional contract represents a trend.',explain:'The speaker advises caution about interpreting one unusually large contract as evidence of a lasting trend.',model:'surface positive → however → caution about generalising.'}
];

const writingTasks=[
{type:'PROFESSIONAL EMAIL',title:'Delivery delay and next steps',prompt:'A supplier has informed you that a delivery will arrive two days late. Write to an internal colleague. Explain the new date, the possible impact on the project, what you have asked the supplier to do, and what action you recommend internally.',requirements:['new delivery date','possible impact','supplier follow-up','recommended action'],m1:`The supplier has confirmed that the delivery will arrive on Thursday instead of Tuesday. This may delay the installation by one day. I have asked the supplier whether a partial delivery is possible. In the meantime, I recommend that we adjust the installation schedule and confirm the new plan with the team.`,m2:`I wanted to update you on the delivery schedule. The supplier has confirmed a two-day delay, with delivery now expected on Thursday. This could affect the planned installation and create a one-day knock-on delay for the project. I have asked whether a partial shipment can be arranged to protect the critical activities. In parallel, I recommend revising the installation sequence and informing the relevant stakeholders today so that we can minimise disruption.`},
{type:'TECHNICAL NOTE',title:'Recurring connection problem',prompt:'Write a short technical note about a system that disconnects several times a day. State the observed issue, immediate checks already completed, the likely impact, and the recommended next step.',requirements:['observed issue','checks completed','impact','next step'],m1:`Issue: The system disconnects several times each day. Basic network and device checks have been completed, but the problem continues. Impact: Users lose access for several minutes and some work must be restarted. Recommendation: Escalate the issue to the network team for log analysis and monitoring.`,m2:`Observed issue: Users are experiencing repeated system disconnections, typically three to five times per day. Initial device, cable and local network checks have not identified a clear fault. The interruptions are causing short periods of lost access and repeated work for some users. Recommended next step: escalate to the network team for a review of connection logs and live monitoring during the next incident window.`},
{type:'COMPTE RENDU',title:'Short project meeting summary',prompt:'A project meeting ended with three decisions: keep the launch date, revise the customer message by Wednesday, and confirm stock levels before Thursday noon. Write a concise compte rendu including decisions, actions and deadlines.',requirements:['launch decision','marketing action','operations action','deadlines'],m1:`Project meeting summary: The team agreed to keep the current launch date. Marketing will revise the customer message by Wednesday. Operations will confirm stock levels before noon on Thursday. A final status check will take place on Thursday afternoon.`,m2:`Project meeting — key outcomes: The current launch date remains unchanged. Marketing will provide a revised customer communication by Wednesday. Operations is responsible for confirming available stock before 12:00 on Thursday. The team will reconvene on Thursday afternoon for a final go/no-go review based on these actions.`}
];

const oralStages=[
{stage:'PART 1 · INTRODUCTION',title:'Your professional role',prompt:'Tell the evaluator about your current role or professional situation. What are your main responsibilities, and when do you use or expect to use English?',follow:'Possible follow-up: Which situation is the most difficult for you in English, and why?',m1:`I work in a professional team and I have several responsibilities. I communicate with colleagues and sometimes with customers or partners. I need English mainly for emails, meetings and understanding documents. The most difficult situation for me is speaking spontaneously because I need more time to find the right words.`,m2:`In my current role, I coordinate several day-to-day activities and communicate with both internal colleagues and external contacts. English is particularly useful for written communication, meetings and understanding professional documentation. The most challenging part is spontaneous interaction, especially when I need to respond quickly to an unexpected question, so I am working on fluency and clarification strategies.`},
{stage:'PART 2 · PROFESSIONAL ROLE-PLAY',title:'A dissatisfied customer',prompt:'The evaluator is a customer whose order is late for the second time. Acknowledge the frustration, ask one useful question, explain what you can do now, and agree on a follow-up.',follow:'Possible follow-up: The customer says they need the order tomorrow. What can you propose?',m1:`I understand why you are frustrated, especially because this has happened before. Could you confirm which items are most urgent? I will check the current delivery status immediately and see whether we can arrange a partial delivery. I will call you back this afternoon with a clear update.`,m2:`I completely understand your concern, particularly as this is the second delay. Before I look at the available options, could you tell me which items are critical for tomorrow? I will check the shipment status and speak directly with logistics to see whether we can prioritise or split the delivery. I will come back to you by 3 p.m. today with a confirmed solution and next steps.`},
{stage:'PART 3 · PROFESSIONAL DISCUSSION',title:'AI in the workplace',prompt:'Do you think AI will improve most professional jobs, or create more problems than benefits? Give your opinion, at least two reasons, one example and a balanced conclusion.',follow:'Possible follow-up: What should companies do to introduce AI responsibly?',m1:`I think AI can improve many jobs because it can save time and help with repetitive tasks. It can also help people find information quickly. However, employees need training and companies must check the quality of the results. For example, AI can help prepare a first draft, but a person should still review it.`,m2:`Overall, I think AI can improve many professional roles, mainly by reducing repetitive work and supporting faster access to information. However, the benefits depend on how it is introduced. Poorly controlled use can create accuracy, confidentiality or skills-related problems. For example, AI may produce a useful first draft of a report, but professional judgement is still required to verify the content and adapt it to the audience. Companies should therefore combine clear rules, training and human review rather than treating AI as an automatic replacement for expertise.`}
];

function byDomain(){const m={};domainOrder.forEach(d=>m[d]=[]);questions.forEach(q=>m[q.domain].push(q));return m}
function buildSequence(){const map=byDomain();const cycles=[];for(let i=0;i<10;i++)cycles.push(...shuffle(domainOrder));const out=[];cycles.forEach(d=>{const bucket=map[d];const q=bucket.shift();if(q)out.push(q)});return out}

function timeFor(q){if(state.timing==='untimed')return null;return q.domain==='Reading'?75:q.domain==='Listening'?65:50}
function answerMatches(q,val){if(Array.isArray(q.answer))return Array.isArray(val)&&q.answer.length===val.length&&q.answer.every((x,i)=>normalize(x)===normalize(val[i]));const n=normalize(val),targets=[q.answer,...(q.alts||[])].map(normalize);return targets.includes(n)}

function ensureTokens(tokens,answer){const work=[...tokens];const need={};answer.forEach(x=>need[x]=(need[x]||0)+1);for(const [tok,count] of Object.entries(need)){let have=work.filter(x=>x===tok).length;while(have<count){work.push(tok);have++}}return work}

function renderInput(q,host,mode='mock'){
  if(q.context){const c=document.createElement('div');c.className='mock-context';c.textContent=q.context;host.appendChild(c)}
  const p=document.createElement('div');p.className='mock-prompt';p.textContent=q.prompt;host.appendChild(p);
  if(q.type==='choice'||q.type==='listen-choice'){
    const wrap=document.createElement('div');wrap.className='choice-list';q.choices.forEach(c=>{const b=document.createElement('button');b.type='button';b.textContent=c;b.dataset.value=c;b.onclick=()=>{$$('button',wrap).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')};wrap.appendChild(b)});host.appendChild(wrap)
  } else if(q.type==='select'){
    const s=document.createElement('select');s.className='q-select';s.innerHTML='<option value="">Select an answer…</option>'+q.choices.map(c=>`<option>${c}</option>`).join('');host.appendChild(s)
  } else if(q.type==='input'||q.type==='listen-input'){
    const i=document.createElement('input');i.className='q-input';i.type='text';i.autocomplete='off';i.placeholder='Type your answer…';host.appendChild(i)
  } else if(q.type==='wordbank'){
    const wrap=document.createElement('div');wrap.className='wordbank';shuffle(q.tokens).forEach(t=>{const b=document.createElement('button');b.type='button';b.textContent=t;b.dataset.value=t;b.onclick=()=>{$$('button',wrap).forEach(x=>x.classList.remove('selected'));b.classList.add('selected')};wrap.appendChild(b)});host.appendChild(wrap)
  } else if(q.type==='reorder'||q.type==='textorder'){
    const tokens=shuffle(ensureTokens(q.tokens,q.answer));const bank=document.createElement('div');bank.className='word-order-bank';const ans=document.createElement('div');ans.className='word-order-answer';tokens.forEach((t,idx)=>{const b=document.createElement('button');b.type='button';b.className='token-btn';b.textContent=t;b.dataset.token=t;b.dataset.idx=String(idx);b.onclick=()=>{b.classList.add('hidden');const a=document.createElement('button');a.type='button';a.className='answer-token';a.textContent=t;a.dataset.token=t;a.dataset.source=String(idx);a.onclick=()=>{const src=$(`[data-idx="${a.dataset.source}"]`,bank);if(src)src.classList.remove('hidden');a.remove()};ans.appendChild(a)};bank.appendChild(b)});host.append(bank,ans)
  }
  if(q.type.startsWith('listen')){
    const panel=document.createElement('div');panel.className='audio-panel';panel.innerHTML=`<button type="button" class="play-audio">▶ Play extract</button><span class="play-count">0 / 2 plays</span>`;let plays=0;$('.play-audio',panel).onclick=()=>{if(plays>=2)return;plays++;$('.play-count',panel).textContent=`${plays} / 2 plays`;speak(q.audio);if(plays>=2)$('.play-audio',panel).disabled=true};host.insertBefore(panel,p)
  }
}
function getAnswer(host,q){
  if(q.type==='choice'||q.type==='listen-choice')return $('.choice-list button.selected',host)?.dataset.value||'';
  if(q.type==='select')return $('.q-select',host)?.value||'';
  if(q.type==='input'||q.type==='listen-input')return $('.q-input',host)?.value||'';
  if(q.type==='wordbank')return $('.wordbank button.selected',host)?.dataset.value||'';
  if(q.type==='reorder'||q.type==='textorder')return $$('.word-order-answer .answer-token',host).map(x=>x.dataset.token);
  return '';
}
function speak(text){if(!('speechSynthesis'in window)){toast('Audio is not available in this browser.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.92;speechSynthesis.speak(u)}

function progress(){const pct=Math.round(state.sections.size/5*100);$('#progressLabel').textContent=`${pct}% complete`;$('#headerProgress').style.width=pct+'%'}
$$('[data-scroll]').forEach(b=>b.onclick=()=>$(b.dataset.scroll)?.scrollIntoView({behavior:'smooth'}));
$$('.section-done').forEach(b=>b.onclick=()=>{state.sections.add(Number(b.dataset.complete));b.classList.add('done');b.textContent='✓ Section completed';progress()});
$('#toggleFrench').onclick=()=>{document.body.classList.toggle('fr-hidden');toast(document.body.classList.contains('fr-hidden')?'FR Coach hidden':'FR Coach visible')};
setInterval(()=>{const sec=Math.floor((Date.now()-state.started)/1000);$('#lessonClock').textContent=`${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`},1000);

$$('.launch-option').forEach(b=>b.onclick=()=>{$$('.launch-option').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.timing=b.dataset.timing});
function save(){const data={timing:state.timing,tokens:state.tokens,index:state.index,answers:state.answers,questionIds:state.questions.map(q=>q.id),sections:[...state.sections]};localStorage.setItem(STORAGE,JSON.stringify(data))}
function loadSaved(){try{return JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{return null}}
function checkSaved(){const s=loadSaved();if(s&&Array.isArray(s.questionIds)&&s.index<50)$('#savedBanner').classList.add('show')}
function startFresh(){state.questions=buildSequence();state.index=0;state.tokens=5;state.answers=[];state.checkpointStart=0;localStorage.removeItem(STORAGE);$('#mockLaunch').classList.add('hidden');$('#checkpointPanel').classList.add('hidden');$('#fullResults').classList.add('hidden');$('#mockShell').classList.remove('hidden');renderQuestion()}
$('#startMock').onclick=startFresh;
$('#discardSaved').onclick=()=>{localStorage.removeItem(STORAGE);$('#savedBanner').classList.remove('show');toast('Saved attempt discarded')};
$('#resumeMock').onclick=()=>{const s=loadSaved();if(!s)return startFresh();const byId=Object.fromEntries(questions.map(q=>[q.id,q]));state.questions=s.questionIds.map(id=>byId[id]).filter(Boolean);state.timing=s.timing||'timed';state.tokens=Number.isFinite(s.tokens)?s.tokens:5;state.index=s.index||0;state.answers=Array.isArray(s.answers)?s.answers:[];state.sections=new Set(s.sections||[]);state.checkpointStart=Math.floor(state.index/10)*10;progress();$('#mockLaunch').classList.add('hidden');$('#mockShell').classList.remove('hidden');$('#savedBanner').classList.remove('show');renderQuestion()};

function renderQuestion(){
  clearInterval(state.timer);const q=state.questions[state.index],host=$('#mockHost');$('#mockCounter').textContent=`${state.index+1} / 50`;$('#tokenCount').textContent=state.tokens;host.innerHTML='';
  const meta=document.createElement('div');meta.className='mock-meta';meta.innerHTML=`<div class="mock-meta-left"><span class="mock-chip domain">${q.domain}</span><span class="mock-chip">${q.level}</span></div><span class="mock-chip">${state.timing==='timed'?'Timed':'Untimed'}</span>`;host.appendChild(meta);
  renderInput(q,host,'mock');
  const coach=document.createElement('div');coach.className='coach-reveal';coach.innerHTML=`<b>Coach hint</b><p>${q.hint}</p>`;host.appendChild(coach);
  const actions=document.createElement('div');actions.className='mock-actions';actions.innerHTML=`<button class="coach-button use-coach" ${state.tokens<=0?'disabled':''}>🎟 Use Coach Token</button><button class="button primary validate-q">Validate answer</button>`;host.appendChild(actions);
  $('.use-coach',actions).onclick=()=>{if(state.tokens<=0||coach.classList.contains('show'))return;state.tokens--;$('#tokenCount').textContent=state.tokens;coach.classList.add('show');$('.use-coach',actions).disabled=true;save()};
  $('.validate-q',actions).onclick=()=>submitCurrent(false,host,q);
  const t=timeFor(q),track=$('#mockTrack');track.style.width='100%';track.style.background='var(--green)';
  if(t){state.left=t;const timer=document.createElement('div');timer.className='clock-pill';timer.style.marginLeft='auto';timer.innerHTML=`◷ <b id="liveQuestionTimer">${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}</b>`;meta.appendChild(timer);state.timer=setInterval(()=>{state.left--;const e=$('#liveQuestionTimer');if(e)e.textContent=`${String(Math.floor(Math.max(0,state.left)/60)).padStart(2,'0')}:${String(Math.max(0,state.left)%60).padStart(2,'0')}`;const pct=Math.max(0,state.left/t*100);track.style.width=pct+'%';track.style.background=pct>50?'var(--green)':pct>25?'var(--yellow)':'var(--red)';if(state.left<=0){clearInterval(state.timer);submitCurrent(true,host,q)}},1000)}
}
function submitCurrent(timeout,host,q){
  clearInterval(state.timer);let val=timeout?'':getAnswer(host,q);if(!timeout){if((Array.isArray(val)&&!val.length)||(!Array.isArray(val)&&!String(val).trim())){toast('Choose or type an answer first.');return}}
  const ok=answerMatches(q,val);state.answers.push({id:q.id,domain:q.domain,level:q.level,user:answerText(val),correct:answerText(q.answer),ok,explain:q.explain,model:q.model,audio:q.audio||''});state.index++;save();
  host.innerHTML=`<div class="transition-screen"><span>${timeout?'Time. Your response was recorded.':'Answer recorded.'}</span><br><b>Next question in 3…</b></div>`;let n=3;const step=setInterval(()=>{n--;const b=$('.transition-screen b',host);if(b)b.textContent=n?`Next question in ${n}…`:'Loading…';if(n<=0){clearInterval(step);if(state.index>=50)return finishMock();if(state.index%10===0)return showCheckpoint();renderQuestion()}},1000)
}
function showCheckpoint(){
  $('#mockShell').classList.add('hidden');const panel=$('#checkpointPanel');panel.classList.remove('hidden');const start=state.index-10,block=state.answers.slice(start,state.index),correct=block.filter(a=>a.ok).length;panel.innerHTML=`<div class="checkpoint-head"><div><span class="kicker">CHECKPOINT · QUESTIONS ${start+1}–${state.index}</span><h3>Review before you continue</h3></div><div class="checkpoint-score">${correct} / 10</div></div><div class="checkpoint-list">${block.map((a,i)=>`<article class="checkpoint-item ${a.ok?'good':'bad'}"><b>${start+i+1}. ${a.domain} · ${a.ok?'Correct':'Review'}</b><p><strong>Your answer:</strong> ${a.user||'—'}<br><strong>Correct answer:</strong> ${a.correct}</p><p>${a.explain}</p><div class="thinking"><strong>Model thinking:</strong> ${a.model}</div>${a.audio?`<p><strong>Listening transcript:</strong> ${a.audio}</p>`:''}</article>`).join('')}</div><div class="checkpoint-actions"><button class="button primary continue-mock">Continue to question ${state.index+1}</button><button class="button ghost save-stop">Save & stop here</button></div>`;
  $('.continue-mock',panel).onclick=()=>{panel.classList.add('hidden');$('#mockShell').classList.remove('hidden');renderQuestion()};$('.save-stop',panel).onclick=()=>{save();toast('Progress saved on this device');$('#mockLaunch').classList.remove('hidden');$('#savedBanner').classList.add('show');panel.classList.add('hidden');$('#mockLaunch').scrollIntoView({behavior:'smooth'})};panel.scrollIntoView({behavior:'smooth'})
}
function finishMock(){
  localStorage.removeItem(STORAGE);$('#mockShell').classList.add('hidden');$('#checkpointPanel').classList.add('hidden');const p=$('#fullResults');p.classList.remove('hidden');const correct=state.answers.filter(a=>a.ok).length,pct=Math.round(correct/50*100);const domains={};domainOrder.forEach(d=>domains[d]={c:0,n:0});state.answers.forEach(a=>{domains[a.domain].n++;if(a.ok)domains[a.domain].c++});const weak=Object.entries(domains).sort((a,b)=>(a[1].c/a[1].n)-(b[1].c/b[1].n)).slice(0,2).map(x=>x[0]);p.innerHTML=`<div class="big-result"><div class="big-ring" style="--pct:${pct}%"><strong>${pct}%</strong></div><div><span class="kicker">WRITTEN REHEARSAL COMPLETE</span><h2>${correct} / 50 correct</h2><p>This is a training score, not an official CLOE result. Your strongest preparation move now is to review the weakest domains before attempting the independent final mock.</p><p><b>Priority review:</b> ${weak.join(' · ')}</p></div></div><div class="five-domain-results">${domainOrder.map(d=>`<article><b>${domains[d].c}/${domains[d].n}</b><span>${d}</span></article>`).join('')}</div><div class="final-actions"><button class="button primary show-final-review">Open complete 50-question review</button><button class="button ghost go-writing">Continue to writing transfer</button></div><div class="review-list hidden" id="finalReview">${state.answers.map((a,i)=>`<article class="review-item ${a.ok?'good':'bad'}"><b>${i+1}. ${a.domain} · ${a.level}</b><p><strong>Your answer:</strong> ${a.user||'—'}<br><strong>Correct answer:</strong> ${a.correct}</p><p>${a.explain}</p><p><strong>Model thinking:</strong> ${a.model}</p>${a.audio?`<p><strong>Transcript:</strong> ${a.audio}</p>`:''}</article>`).join('')}</div>`;$('.show-final-review',p).onclick=()=>$('#finalReview').classList.toggle('hidden');$('.go-writing',p).onclick=()=>$('#writingTransfer').scrollIntoView({behavior:'smooth'});state.report={correct,total:50,pct,domains,weak,answers:state.answers,finished:new Date().toISOString()};state.sections.add(3);progress();p.scrollIntoView({behavior:'smooth'})
}

function renderWriting(){const host=$('#writingGrid');writingTasks.forEach((t,i)=>{const a=document.createElement('article');a.className='production-card';a.innerHTML=`<span class="type">${t.type}</span><h3>${t.title}</h3><p>${t.prompt}</p><ul>${t.requirements.map(r=>`<li>${r}</li>`).join('')}</ul><textarea placeholder="Plan and write your answer here…"></textarea><button class="model-toggle">Show two model levels</button><div class="production-models"><article><b>Model 1 · Clear & accessible</b><p>${t.m1}</p><button class="button ghost small speak-write" data-text="${encodeURIComponent(t.m1)}">🔊 Listen</button></article><article><b>Model 2 · Stronger</b><p>${t.m2}</p><button class="button ghost small speak-write" data-text="${encodeURIComponent(t.m2)}">🔊 Listen</button></article></div>`;$('.model-toggle',a).onclick=()=>$('.production-models',a).classList.toggle('show');host.appendChild(a)});$$('.speak-write').forEach(b=>b.onclick=()=>speak(decodeURIComponent(b.dataset.text)))}
function renderOral(){const host=$('#oralGrid');oralStages.forEach(s=>{const a=document.createElement('article');a.className='oral-stage-card';a.innerHTML=`<span class="stage">${s.stage}</span><h3>${s.title}</h3><div class="promptbox"><b>Examiner prompt</b><p>${s.prompt}</p><small>${s.follow}</small></div><textarea placeholder="Prepare key words only, then speak aloud without reading…"></textarea><button class="model-toggle">Show two model levels</button><div class="oral-models"><article><b>Model 1 · Clear & accessible</b><p>${s.m1}</p><button class="button ghost small speak-oral" data-text="${encodeURIComponent(s.m1)}">🔊 Listen</button></article><article><b>Model 2 · Stronger</b><p>${s.m2}</p><button class="button ghost small speak-oral" data-text="${encodeURIComponent(s.m2)}">🔊 Listen</button></article></div>`;$('.model-toggle',a).onclick=()=>$('.oral-models',a).classList.toggle('show');host.appendChild(a)});$$('.speak-oral').forEach(b=>b.onclick=()=>speak(decodeURIComponent(b.dataset.text)))}

function download(filename,text,type='text/plain'){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500)}
$('#downloadReport').onclick=()=>{let txt='CLOE Success Path · Lesson 9\nComplete Guided Mock\n\n';if(state.report.total){txt+=`Written rehearsal: ${state.report.correct}/${state.report.total} (${state.report.pct}%)\n\nDomain results:\n`;domainOrder.forEach(d=>{const v=state.report.domains[d];txt+=`${d}: ${v.c}/${v.n}\n`});txt+=`\nPriority review: ${state.report.weak.join(', ')}\n`}else txt+='Written rehearsal not yet completed.\n';txt+='\nTraining note: this is a practice report, not an official CLOE result.\n';download('CLOE_Lesson_09_Report.txt',txt)};
$('#exportProgress').onclick=()=>download('CLOE_Lesson_09_Progress.json',JSON.stringify({sections:[...state.sections],report:state.report},null,2),'application/json');
$('#resetAll').onclick=()=>{if(!confirm('Reset all Lesson 9 progress?'))return;clearInterval(state.timer);localStorage.removeItem(STORAGE);state.sections.clear();state.timing='timed';state.tokens=5;state.index=0;state.answers=[];state.questions=[];state.report={};$$('.section-done').forEach(b=>{b.classList.remove('done');b.textContent='✓ '+(b.dataset.complete==='1'?'I understand the rehearsal':b.dataset.complete==='2'?'I will use coaching strategically':b.dataset.complete==='4'?'I completed a writing transfer':b.dataset.complete==='5'?'I completed Lesson 9':'Section')});$$('.launch-option').forEach((b,i)=>b.classList.toggle('active',i===0));$('#mockLaunch').classList.remove('hidden');$('#mockShell').classList.add('hidden');$('#checkpointPanel').classList.add('hidden');$('#fullResults').classList.add('hidden');$('#savedBanner').classList.remove('show');progress();toast('Lesson reset')};

renderWriting();renderOral();checkSaved();progress();
})();
